def min_rows_for_mirror(a):
    n, m = len(a), len(a[0])
    result = 0

    for j in range(m):
        left, right = 0, n - 1
        while left < right:
            if a[left][j] == a[right][j]:
                left += 1
                right -= 1
            else:
                break

        if left >= right:
            result += 1

    return result

